"""Execute a parsed query (see ast.py) against CSV files. See SPEC.md.

Pipeline: load table -> WHERE -> (grouping -> HAVING) -> project ->
ORDER BY -> DISTINCT -> OFFSET/LIMIT.

Before touching any rows the whole query is checked statically: column
names, function names and argument counts, aggregate placement, ORDER BY
ordinals and the grouped-column rule. So these errors are reported even
when the table (or the WHERE result) is empty. Type errors can only be
found while evaluating, so they surface only when a value is computed.
"""

import csv
import decimal
import functools
import os
import re

from . import ast
from .errors import QueryError

__all__ = ["Result", "execute"]


class Result:
    """The result of a query: ``columns`` (list of str), ``rows`` (list of tuples)."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns={!r}, rows={!r})".format(self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


def execute(query, directory):
    """Run ``query`` (an ``ast.Query``) against the CSV files in ``directory``."""
    if not isinstance(query, ast.Query):
        raise QueryError("expected a parsed query")
    try:
        return _Executor(query, directory).run()
    except QueryError:
        raise
    except RecursionError:
        raise QueryError("query is too deeply nested") from None
    except (ArithmeticError, ValueError, TypeError) as exc:  # safety net
        raise QueryError("error evaluating query: {}".format(exc)) from None


# ---------------------------------------------------------------------------
# Values

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def _convert_field(text):
    if text == "":
        return None
    if _INT_RE.fullmatch(text):
        try:
            return int(text)
        except ValueError:  # e.g. int max str digits limit (3.11+)
            raise QueryError("integer too large: {}".format(text[:40])) from None
    if _FLOAT_RE.fullmatch(text):
        return float(text)
    return text


def _is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _kind(v):
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, (int, float)):
        return "number"
    if isinstance(v, str):
        return "string"
    if v is None:
        return "NULL"
    raise QueryError("unsupported value {!r}".format(v))


def _compare(a, b):
    """Compare two non-NULL values: -1, 0 or 1. Mismatched kinds are an error."""
    ka, kb = _kind(a), _kind(b)
    if ka != kb:
        raise QueryError("cannot compare {} with {}".format(ka, kb))
    return (a > b) - (a < b)


def _value_key(v):
    """A hashable key that keeps TRUE and 1 apart (1 and 1.0 stay equal)."""
    return (_kind(v), v)


def _text(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


def _like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def _not3(v):
    return None if v is None else (not v)


def _and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or3(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _check_bool(v, what):
    if v is not None and not isinstance(v, bool):
        raise QueryError("{} needs a boolean, got {}".format(what, _kind(v)))


def _to_decimal(x):
    d = decimal.Decimal(repr(x)) if isinstance(x, float) else decimal.Decimal(x)
    if not d.is_finite():
        raise QueryError("cannot round {}".format(x))
    return d


def _quantize_half_up(d, exp):
    """Round Decimal ``d`` to a multiple of 10**exp, halves away from zero."""
    if d.as_tuple().exponent >= exp:
        return d  # already exact at this precision
    if exp > d.adjusted() + 1:
        return decimal.Decimal(0)
    ctx = decimal.Context(
        prec=max(28, d.adjusted() - exp + 3),
        rounding=decimal.ROUND_HALF_UP,
        Emax=decimal.MAX_EMAX,
        Emin=decimal.MIN_EMIN,
    )
    return d.quantize(decimal.Decimal((0, (1,), exp)), context=ctx)


def _round(x, n=None):
    if n is None:
        if isinstance(x, int):
            return x
        return int(_quantize_half_up(_to_decimal(x), 0))
    if not isinstance(n, int) or isinstance(n, bool):
        raise QueryError("ROUND places must be an integer, got {}".format(_kind(n)))
    try:
        result = float(_quantize_half_up(_to_decimal(x), -n))
    except decimal.DecimalException:
        raise QueryError("cannot round {} to {} places".format(x, n)) from None
    return result + 0.0  # normalize -0.0 to 0.0


# ---------------------------------------------------------------------------
# Functions

_AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
# name -> (min args, max args or None)
_SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


def _is_aggregate(expr):
    return isinstance(expr, ast.Call) and expr.name.upper() in _AGGREGATES


def _children(expr):
    if isinstance(expr, (ast.Literal, ast.Name)):
        return []
    if isinstance(expr, ast.Unary):
        return [expr.operand]
    if isinstance(expr, ast.Binary):
        return [expr.left, expr.right]
    if isinstance(expr, ast.IsNull):
        return [expr.operand]
    if isinstance(expr, ast.In):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, ast.Between):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, ast.Like):
        return [expr.operand, expr.pattern]
    if isinstance(expr, ast.Call):
        return list(expr.args)
    raise QueryError("unsupported expression {!r}".format(expr))


def _contains_aggregate(expr):
    if _is_aggregate(expr):
        return True
    return any(_contains_aggregate(c) for c in _children(expr))


def _skey(expr):
    """Structural key for comparing expressions (names case-insensitive,
    literals type-aware so TRUE != 1)."""
    if isinstance(expr, ast.Literal):
        return ("lit", _kind(expr.value), expr.value)
    if isinstance(expr, ast.Name):
        return ("name", expr.name.lower())
    if isinstance(expr, ast.Unary):
        return ("unary", expr.op.upper(), _skey(expr.operand))
    if isinstance(expr, ast.Binary):
        return ("bin", expr.op.upper(), _skey(expr.left), _skey(expr.right))
    if isinstance(expr, ast.IsNull):
        return ("isnull", bool(expr.negated), _skey(expr.operand))
    if isinstance(expr, ast.In):
        return ("in", bool(expr.negated), _skey(expr.operand),
                tuple(_skey(i) for i in expr.items))
    if isinstance(expr, ast.Between):
        return ("between", bool(expr.negated), _skey(expr.operand),
                _skey(expr.low), _skey(expr.high))
    if isinstance(expr, ast.Like):
        return ("like", bool(expr.negated), _skey(expr.operand), _skey(expr.pattern))
    if isinstance(expr, ast.Call):
        return ("call", expr.name.upper(), bool(expr.star),
                tuple(_skey(a) for a in expr.args))
    raise QueryError("unsupported expression {!r}".format(expr))


# ---------------------------------------------------------------------------
# Tables


def _find_table(name, directory):
    if not name or "/" in name or "\\" in name or "\0" in name or name in (".", ".."):
        raise QueryError("invalid table name: {}".format(name))
    path = os.path.join(directory, name + ".csv")
    if os.path.isfile(path):
        return path
    # Fall back to a unique case-insensitive match.
    try:
        entries = os.listdir(directory)
    except OSError:
        raise QueryError("cannot read directory: {}".format(directory)) from None
    target = (name + ".csv").lower()
    matches = [e for e in entries
               if e.lower() == target and os.path.isfile(os.path.join(directory, e))]
    if len(matches) == 1:
        return os.path.join(directory, matches[0])
    if len(matches) > 1:
        raise QueryError("ambiguous table name: {}".format(name))
    raise QueryError("unknown table: {}".format(name))


def _load_table(name, directory):
    path = _find_table(name, directory)
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            records = [r for r in csv.reader(f) if r]  # skip blank lines
    except (OSError, UnicodeDecodeError, csv.Error) as exc:
        raise QueryError("cannot read table {}: {}".format(name, exc)) from None
    if not records:
        raise QueryError("table {} has no header".format(name))
    header = records[0]
    rows = []
    for lineno, rec in enumerate(records[1:], start=2):
        if len(rec) != len(header):
            raise QueryError("table {}: row {} has {} fields, header has {}".format(
                name, lineno, len(rec), len(header)))
        rows.append(tuple(_convert_field(v) for v in rec))
    return header, rows


# ---------------------------------------------------------------------------
# Executor


class _Group:
    __slots__ = ("values", "rows")

    def __init__(self, values):
        self.values = values  # GROUP BY values from the group's first row
        self.rows = []


class _Executor:
    def __init__(self, query, directory):
        self.q = query
        self.header, self.rows = _load_table(query.table, directory)
        self.colmap = {}
        for i, h in enumerate(self.header):
            self.colmap.setdefault(h.lower(), []).append(i)
        self.like_cache = {}
        self.gb_index = {}

    # -- names --------------------------------------------------------------

    def resolve(self, name):
        idxs = self.colmap.get(name.lower(), [])
        if len(idxs) == 1:
            return idxs[0]
        if not idxs:
            raise QueryError("unknown column: {}".format(name))
        exact = [i for i in idxs if self.header[i] == name]
        if len(exact) == 1:
            return exact[0]
        raise QueryError("ambiguous column: {}".format(name))

    # -- static checks ------------------------------------------------------

    def check(self, expr, allow_agg, where, in_agg=False):
        if isinstance(expr, ast.Name):
            self.resolve(expr.name)
            return
        if isinstance(expr, ast.Literal):
            _kind(expr.value)
            return
        if isinstance(expr, ast.Unary) and expr.op.upper() not in ("-", "NOT"):
            raise QueryError("unknown operator {}".format(expr.op))
        if isinstance(expr, ast.Call):
            name = expr.name.upper()
            nargs = len(expr.args)
            if name in _AGGREGATES:
                if in_agg:
                    raise QueryError("aggregates can't be nested")
                if not allow_agg:
                    raise QueryError("aggregates can't be used in {}".format(where))
                if expr.star:
                    if name != "COUNT" or nargs:
                        raise QueryError("{}(*) is not allowed".format(name))
                elif nargs != 1:
                    raise QueryError("{} takes 1 argument, got {}".format(name, nargs))
                for a in expr.args:
                    self.check(a, allow_agg, where, in_agg=True)
                return
            if name not in _SCALARS:
                raise QueryError("unknown function: {}".format(expr.name))
            if expr.star:
                raise QueryError("{}(*) is not allowed".format(name))
            lo, hi = _SCALARS[name]
            if nargs < lo or (hi is not None and nargs > hi):
                raise QueryError("wrong number of arguments to {}: {}".format(name, nargs))
        for c in _children(expr):
            self.check(c, allow_agg, where, in_agg)

    def check_grouped(self, expr):
        """In a grouped query, columns outside aggregates must be inside a
        GROUP BY expression."""
        if _skey(expr) in self.gb_index or _is_aggregate(expr):
            return
        if isinstance(expr, ast.Name):
            raise QueryError(
                "column {} must appear in GROUP BY or be used in an aggregate".format(
                    expr.name))
        for c in _children(expr):
            self.check_grouped(c)

    # -- evaluation ---------------------------------------------------------

    def ev(self, expr, row, group=None):
        """Evaluate ``expr`` on an input row, or (``group`` given) on a group."""
        if group is not None:
            i = self.gb_index.get(_skey(expr))
            if i is not None:
                return group.values[i]
            if _is_aggregate(expr):
                return self.aggregate(expr, group.rows)
        if isinstance(expr, ast.Literal):
            return expr.value
        if isinstance(expr, ast.Name):
            if group is not None:  # prevented by check_grouped
                raise QueryError("column {} is not grouped".format(expr.name))
            return row[self.resolve(expr.name)]
        if isinstance(expr, ast.Unary):
            v = self.ev(expr.operand, row, group)
            op = expr.op.upper()
            if op == "NOT":
                _check_bool(v, "NOT")
                return _not3(v)
            if op == "-":
                if v is None:
                    return None
                if not _is_number(v):
                    raise QueryError("cannot negate a {}".format(_kind(v)))
                return -v
            raise QueryError("unknown operator {}".format(expr.op))
        if isinstance(expr, ast.Binary):
            return self.binary(expr.op.upper(), self.ev(expr.left, row, group),
                               self.ev(expr.right, row, group))
        if isinstance(expr, ast.IsNull):
            v = self.ev(expr.operand, row, group)
            return (v is not None) if expr.negated else (v is None)
        if isinstance(expr, ast.In):
            x = self.ev(expr.operand, row, group)
            items = [self.ev(i, row, group) for i in expr.items]
            found = False
            saw_null = x is None
            for item in items:
                if item is None:
                    saw_null = True
                elif x is not None and _compare(x, item) == 0:
                    found = True
            result = True if found else (None if saw_null else False)
            return _not3(result) if expr.negated else result
        if isinstance(expr, ast.Between):
            x = self.ev(expr.operand, row, group)
            lo = self.ev(expr.low, row, group)
            hi = self.ev(expr.high, row, group)
            result = _and3(self.binary("<=", lo, x), self.binary("<=", x, hi))
            return _not3(result) if expr.negated else result
        if isinstance(expr, ast.Like):
            s = self.ev(expr.operand, row, group)
            p = self.ev(expr.pattern, row, group)
            for v in (s, p):
                if v is not None and not isinstance(v, str):
                    raise QueryError("LIKE needs strings, got {}".format(_kind(v)))
            if s is None or p is None:
                return None
            rx = self.like_cache.get(p)
            if rx is None:
                rx = self.like_cache[p] = _like_regex(p)
            result = rx.fullmatch(s) is not None
            return (not result) if expr.negated else result
        if isinstance(expr, ast.Call):
            if _is_aggregate(expr):  # prevented by static checks
                raise QueryError("aggregate not allowed here")
            return self.scalar(expr.name.upper(),
                               [self.ev(a, row, group) for a in expr.args])
        raise QueryError("unsupported expression {!r}".format(expr))

    def binary(self, op, a, b):
        if op in ("AND", "OR"):
            _check_bool(a, op)
            _check_bool(b, op)
            return _and3(a, b) if op == "AND" else _or3(a, b)
        if a is None or b is None:
            if op in ("=", "!=", "<>", "<", "<=", ">", ">=", "+", "-", "*", "/", "||"):
                return None
            raise QueryError("unknown operator {}".format(op))
        if op == "||":
            return _text(a) + _text(b)
        if op in ("+", "-", "*", "/"):
            if not _is_number(a) or not _is_number(b):
                raise QueryError("cannot use {} on {} and {}".format(op, _kind(a), _kind(b)))
            try:
                if op == "+":
                    r = a + b
                elif op == "-":
                    r = a - b
                elif op == "*":
                    r = a * b
                else:
                    if b == 0:
                        return None
                    return float(a / b)
            except OverflowError:
                raise QueryError("numeric overflow in {}".format(op)) from None
            if isinstance(a, int) and isinstance(b, int):
                return r
            return float(r)
        c = _compare(a, b)
        if op == "=":
            return c == 0
        if op in ("!=", "<>"):
            return c != 0
        if op == "<":
            return c < 0
        if op == "<=":
            return c <= 0
        if op == ">":
            return c > 0
        if op == ">=":
            return c >= 0
        raise QueryError("unknown operator {}".format(op))

    def scalar(self, name, args):
        if name == "COALESCE":
            for a in args:
                if a is not None:
                    return a
            return None
        if any(a is None for a in args):
            return None
        x = args[0]
        if name in ("LOWER", "UPPER", "LENGTH"):
            if not isinstance(x, str):
                raise QueryError("{} needs a string, got {}".format(name, _kind(x)))
            if name == "LOWER":
                return x.lower()
            if name == "UPPER":
                return x.upper()
            return len(x)
        if not _is_number(x):
            raise QueryError("{} needs a number, got {}".format(name, _kind(x)))
        if name == "ABS":
            return abs(x)
        if name == "ROUND":
            return _round(x, *args[1:])
        raise QueryError("unknown function: {}".format(name))

    def aggregate(self, call, rows):
        name = call.name.upper()
        if call.star:
            return len(rows)
        arg = call.args[0]
        values = [v for v in (self.ev(arg, r) for r in rows) if v is not None]
        if name == "COUNT":
            return len(values)
        if not values:
            return None
        if name in ("SUM", "AVG"):
            for v in values:
                if not _is_number(v):
                    raise QueryError("{} needs numbers, got {}".format(name, _kind(v)))
            try:
                total = sum(values)
                if name == "AVG":
                    return float(total / len(values))
                if all(isinstance(v, int) for v in values):
                    return total
                return float(total)
            except OverflowError:
                raise QueryError("numeric overflow in {}".format(name)) from None
        best = values[0]
        for v in values[1:]:
            c = _compare(v, best)
            if (c < 0) if name == "MIN" else (c > 0):
                best = v
        return best

    # -- the query ------------------------------------------------------------

    def run(self):
        q = self.q

        # Output columns.
        if q.columns is None:
            columns = [ast.SelectColumn(ast.Name(h), None, h) for h in self.header]
        else:
            columns = list(q.columns)
        if not columns:
            raise QueryError("no columns selected")
        names = []
        for col in columns:
            if col.alias is not None:
                names.append(col.alias)
            elif isinstance(col.expr, ast.Name):
                names.append(self.header[self.resolve(col.expr.name)])
            else:
                names.append(col.text)

        # ORDER BY items: ("out", index) or ("expr", expr).
        lowered = [n.lower() for n in names]
        order = []
        for item in q.order_by:
            e = item.expr
            if isinstance(e, ast.Name) and e.name.lower() in lowered:
                order.append(("out", lowered.index(e.name.lower())))
            elif (isinstance(e, ast.Literal) and isinstance(e.value, int)
                  and not isinstance(e.value, bool)):
                if not 1 <= e.value <= len(columns):
                    raise QueryError("ORDER BY position {} is out of range".format(e.value))
                order.append(("out", e.value - 1))
            else:
                order.append(("expr", e))

        # Static checks.
        if q.where is not None:
            self.check(q.where, False, "WHERE")
        for e in q.group_by:
            self.check(e, False, "GROUP BY")
        for col in columns:
            self.check(col.expr, True, "")
        if q.having is not None:
            self.check(q.having, True, "")
        for kind, e in order:
            if kind == "expr":
                self.check(e, True, "")

        for name, v in (("LIMIT", q.limit), ("OFFSET", q.offset)):
            if v is not None and (not isinstance(v, int) or isinstance(v, bool) or v < 0):
                raise QueryError("{} must be a non-negative integer".format(name))

        grouped = (bool(q.group_by) or q.having is not None
                   or any(_contains_aggregate(c.expr) for c in columns)
                   or any(k == "expr" and _contains_aggregate(e) for k, e in order))

        if grouped:
            for i, e in enumerate(q.group_by):
                self.gb_index.setdefault(_skey(e), i)
            for col in columns:
                self.check_grouped(col.expr)
            if q.having is not None:
                self.check_grouped(q.having)
            for kind, e in order:
                if kind == "expr":
                    self.check_grouped(e)

        # WHERE.
        rows = self.rows
        if q.where is not None:
            rows = [r for r in rows if self.ev(q.where, r) is True]

        # Build (output row, order keys) pairs.
        out = []

        def emit(row, group):
            values = tuple(self.ev(c.expr, row, group) for c in columns)
            keys = tuple(values[x] if k == "out" else self.ev(x, row, group)
                         for k, x in order)
            out.append((values, keys))

        if grouped:
            groups = {}
            if not q.group_by:
                groups[()] = _Group([])
            for r in rows:
                vals = [self.ev(e, r) for e in q.group_by]
                key = tuple(_value_key(v) for v in vals)
                g = groups.get(key)
                if g is None:
                    g = groups[key] = _Group(vals)
                g.rows.append(r)
            for g in groups.values():
                if q.having is not None:
                    h = self.ev(q.having, None, g)
                    _check_bool(h, "HAVING")
                    if h is not True:
                        continue
                emit(None, g)
        else:
            for r in rows:
                emit(r, None)

        # ORDER BY.
        if order:
            for i in range(len(order)):
                kinds = {_kind(keys[i]) for _, keys in out if keys[i] is not None}
                if len(kinds) > 1:
                    raise QueryError("cannot sort mixed values: {}".format(
                        ", ".join(sorted(kinds))))
            desc = [item.descending for item in q.order_by]

            def cmp(x, y):
                for a, b, d in zip(x[1], y[1], desc):
                    if a is None and b is None:
                        continue
                    if a is None:
                        c = -1
                    elif b is None:
                        c = 1
                    else:
                        c = _compare(a, b)
                    if c:
                        return -c if d else c
                return 0

            out.sort(key=functools.cmp_to_key(cmp))

        result = [values for values, _ in out]

        # DISTINCT (after sorting, keeping the first in final order).
        if q.distinct:
            seen = set()
            unique = []
            for values in result:
                k = tuple(_value_key(v) for v in values)
                if k not in seen:
                    seen.add(k)
                    unique.append(values)
            result = unique

        start = q.offset or 0
        end = None if q.limit is None else start + q.limit
        return Result(names, result[start:end])

