    return str(value)


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="python -m minisql",
        description="Run a SQL SELECT query against a directory of CSV files.",
    )
    parser.add_argument("query", metavar="QUERY", help="the SELECT query to run")
    parser.add_argument("--dir", default=".", metavar="DIR",
                        help="directory containing the CSV files (default: .)")
    args = parser.parse_args(argv)
    try:
        result = run(args.query, args.dir)
    except QueryError as exc:
        print(exc, file=sys.stderr)
        return 1
    writer = csv.writer(sys.stdout)
    writer.writerow(result.columns)
    for row in result.rows:
        writer.writerow([_field(v) for v in row])
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
